  if(path==='/api/coach/revoke'&&method==='POST'){await run(db,'UPDATE coach_tokens SET revoked_at=? WHERE id=?',now(),b.id);await audit(db,u.id,'revoke_coach_token',String(b.id));return json({ok:true});}
