async function digest(s){return hex(new Uint8Array(await crypto.subtle.digest('SHA-256',enc.encode(s))))}
function cookie(request,token,clear=false){return `clearpath_session=${token}; Path=/; HttpOnly; SameSite=Strict; Max-Age=${clear?0:43200}${new URL(request.url).protocol==='https:'?'; Secure':''}`}
const publicUser=u=>({id:u.id,name:u.name,username:u.username,role:u.role,parent_id:u.parent_id,must_change:!!u.must_change,disabled:!!u.deleted_at});
const one=(db,sql,...args)=>db.prepare(sql).bind(...args).first();
const rows=async(db,sql,...args)=>(await db.prepare(sql).bind(...args).all()).results;
const run=(db,sql,...args)=>db.prepare(sql).bind(...args).run();
async function audit(db,actor,action,target){await run(db,'INSERT INTO audit VALUES (?,?,?,?,?)',id(),actor,action,target,now())}
async function actor(db,request){const token=(request.headers.get('cookie')||'').split(';').map(x=>x.trim()).find(x=>x.startsWith('clearpath_session='))?.slice(18);if(!token)return null;return one(db,'SELECT u.* FROM users u JOIN sessions s ON s.user_id=u.id WHERE s.token_hash=? AND s.expires_at>? AND u.deleted_at IS NULL',await digest(token),now())}
